  // Distance to each bounding plane of the lattice cell.  These are retained
  // so that the crossed boundary can be identified by comparing the per-axis
  // distance to the overall minimum.  Re-evaluating the post-flight position
  // x + u*d instead is numerically unstable: the round-off of the
  // multiply-and-add grows with the coordinate magnitude and can exceed the
  // absolute tolerance FP_PRECISION, which causes the lattice translation to be
  // missed and yields an invalid boundary (no surface and no translation).
  double dx {u.x != 0.0 ? (x0 - x) / u.x : INFTY};
  double dy {u.y != 0.0 ? (y0 - y) / u.y : INFTY};
  double dz {INFTY};
  double d {std::min(dx, dy)};
  if (is_3d_) {
    z0 = copysign(0.5 * pitch_[2], u.z);
    dz = u.z != 0.0 ? (z0 - z) / u.z : INFTY;
    d = std::min(d, dz);
  }

  // Determine which lattice boundaries are being crossed.  Because d is the
  // exact minimum returned by std::min, a boundary is crossed whenever its
  // per-axis distance agrees with d.  A relative tolerance is used so that a
  // particle traversing near a corner of the lattice cell is detected on both
  // axes; the tolerance scales with the distance travelled rather than being a
  // fixed absolute threshold that is defeated by round-off at large
  // coordinates.
  array<int, 3> lattice_trans = {0, 0, 0};
  if (u.x != 0.0 && std::abs(dx - d) <= FP_REL_PRECISION * d)
    lattice_trans[0] = copysign(1, u.x);
  if (u.y != 0.0 && std::abs(dy - d) <= FP_REL_PRECISION * d)
    lattice_trans[1] = copysign(1, u.y);
  if (is_3d_) {
    if (u.z != 0.0 && std::abs(dz - d) <= FP_REL_PRECISION * d)
      lattice_trans[2] = copysign(1, u.z);
  }

  return {d, lattice_trans};
}

